INSERT INTO "cms_faq_item" ("id", "created_at", "updated_at", "created_by_id", "updated_by_id", "category", "question", "answer", "sort_order", "is_active") VALUES ('0e336cd9-ec3b-4c1a-8c3c-3e072becdfde'::uuid, '2026-11-19T08:33:50.439613+00:00'::timestamptz, '2026-11-19T08:33:50.439765+00:00'::timestamptz, NULL, NULL, 'عمومی و ثبت آگهی', 'آیا تمام املاک منتشرشده در پورتال عمومی بنیان ملک دارای مالکیت احراز‌شده هستند؟', 'بله؛ پیش از انتشار عمومی هر ملک، مشخصات سند و فایل توسط مدیر آژانس بررسی و تایید می‌شود و آدرس دقیق تا پیش از هماهنگی بازدید محافظت می‌گردد.', 1, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "cms_faq_item" ("id", "created_at", "updated_at", "created_by_id", "updated_by_id", "category", "question", "answer", "sort_order", "is_active") VALUES ('d39d4771-e7b7-4151-970f-93510625513c'::uuid, '2026-11-19T08:33:50.441728+00:00'::timestamptz, '2026-11-19T08:33:50.441949+00:00'::timestamptz, NULL, NULL, 'آژانس‌ها و اشتراک', 'چگونه آژانس املاک خود را در شبکه بنیان ملک ثبت کنیم؟', 'از طریق صفحه درخواست همکاری آژانس (/agency-application) اطلاعات دفتر و پروانه کسب را ثبت کنید تا پس از تایید بازرسی پلتفرم، پنل اختصاصی آژانس شما فعال شود.', 2, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "cms_faq_item" ("id", "created_at", "updated_at", "created_by_id", "updated_by_id", "category", "question", "answer", "sort_order", "is_active") VALUES ('21aa6c9d-b4a6-4257-992d-4209cdb99c2d'::uuid, '2026-11-19T08:33:50.443465+00:00'::timestamptz, '2026-11-19T08:33:50.443571+00:00'::timestamptz, NULL, NULL, 'کمیسیون و مالی', 'محاسبه سهم مشاور اول، همکار و حسابداری چگونه انجام می‌شود؟', 'مدیر آژانس سیاست‌های نسخه‌دار کمیسیون را تعریف می‌کند؛ پس از بسته‌شدن معامله، سهم‌ها با دقت اعشاری محاسبه و سند حسابداری دوطرفه صادر می‌شود.', 3, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "cms_faq_item" ("id", "created_at", "updated_at", "created_by_id", "updated_by_id", "category", "question", "answer", "sort_order", "is_active") VALUES ('ecd4b8de-266a-4bdc-88dc-c43f88af9650'::uuid, '2026-11-19T08:33:50.445447+00:00'::timestamptz, '2026-11-19T08:33:50.445586+00:00'::timestamptz, NULL, NULL, 'پشتیبانی و پیگیری', 'چگونه می‌توانم وضعیت درخواست یا شکایت ثبت‌شده خود را پیگیری کنم؟', 'با داشتن کد رهگیری (REQ-... یا CMP-...) و شماره موبایل ثبت‌شده، از بخش پیگیری درخواست (/requests/track) یا پیگیری شکایت (/complaints/track) آخرین وضعیت را مشاهده کنید.', 4, TRUE) ON CONFLICT DO NOTHING;
